class Heap {
  constructor(cmp) {
    this.a = []
    this.cmp = cmp
  }
  get size() {
    return this.a.length
  }
  push(x) {
    const a = this.a
    a.push(x)
    let i = a.length - 1
    while (i > 0) {
      const p = (i - 1) >> 1
      if (this.cmp(a[i], a[p]) >= 0) break
      ;[a[i], a[p]] = [a[p], a[i]]
      i = p
    }
  }
  pop() {
    const a = this.a
    const top = a[0]
    const last = a.pop()
    if (a.length) {
      a[0] = last
      let i = 0
      for (;;) {
        const l = 2 * i + 1
        const r = l + 1
        let m = i
        if (l < a.length && this.cmp(a[l], a[m]) < 0) m = l
        if (r < a.length && this.cmp(a[r], a[m]) < 0) m = r
        if (m === i) break
        ;[a[i], a[m]] = [a[m], a[i]]
        i = m
      }
    }
    return top
  }
}

function leastEffort(heights) {
  const rows = heights.length
  const cols = heights[0].length
  const best = heights.map(row => row.map(() => Infinity))
  best[0][0] = 0
  const heap = new Heap((x, y) => x[0] - y[0])
  heap.push([0, 0, 0])
  while (heap.size) {
    const [effort, r, c] = heap.pop()
    if (effort > best[r][c]) continue
    if (r === rows - 1 && c === cols - 1) return effort
    for (const [nr, nc] of [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]]) {
      if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue
      const step = Math.max(effort, Math.abs(heights[nr][nc] - heights[r][c]))
      if (step < best[nr][nc]) {
        best[nr][nc] = step
        heap.push([step, nr, nc])
      }
    }
  }
  return 0
}

